script:
// CRM Lead - Create Menu
// Create > Quotation: opens a Quotation addressed to this CRM Lead (Quotation To = CRM Lead).
//   No Customer is created here - the lead converts to a Customer only when the submitted
//   Quotation's "Order Confirmation" button is used (server API quotation_order_confirm).
// Create > Site Visit: Site Visit requires a Customer, so it still uses/creates the linked Customer
//   via the crm_lead_customer API.

async function cl_get_customer(frm) {
	if (frm.is_dirty()) await frm.save();
	const r = await frappe.call({
		method: "crm_lead_customer",
		args: { lead: frm.doc.name },
		freeze: true,
		freeze_message: __("Preparing customer..."),
	});
	const res = r.message || {};
	if (res.created) {
		frappe.show_alert({ message: __("Customer {0} created from this lead", [res.customer]), indicator: "green" }, 5);
	}
	return res.customer;
}

async function cl_make_quotation(frm) {
	if (frm.is_dirty()) await frm.save();
	const d = frm.doc;
	// If this lead was already converted, quote the existing customer instead
	const existing = await frappe.db.get_value("Customer", { custom_crm_lead: d.name }, "name");
	const customer = existing.message && existing.message.name;
	frappe.model.with_doctype("Quotation", () => {
		const q = frappe.model.get_new_doc("Quotation");
		if (customer) {
			q.quotation_to = "Customer";
			q.party_name = customer;
		} else {
			q.quotation_to = "CRM Lead";
			q.party_name = d.name;
			q.customer_name = d.lead_name || d.first_name;
			q.contact_mobile = d.mobile_no || undefined;
			q.contact_email = d.email || undefined;
		}
		if (d.custom_capacity) q.custom_total_capacity = d.custom_capacity;
		frappe.set_route("Form", "Quotation", q.name);
	});
}

async function cl_make_site_visit(frm) {
	try {
		const customer = await cl_get_customer(frm);
		const emp = await frappe.db.get_value("Employee", { user_id: frappe.session.user, status: "Active" }, "name");
		const d = frm.doc;
		frappe.new_doc("Site Visit", {
			customer: customer,
			employee: (emp.message && emp.message.name) || undefined,
			company: frappe.defaults.get_user_default("Company"),
			contact_person: d.lead_name || d.first_name,
			phone: d.mobile_no || undefined,
			location_site_address: [d.custom_location, d.custom_district].filter(Boolean).join(", ") || undefined,
		});
	} catch (e) {
		console.error(e);
		frappe.msgprint(__("Could not create the Site Visit. Check the lead's name and mobile number."));
	}
}

frappe.ui.form.on("CRM Lead", {
	refresh(frm) {
		if (frm.is_new()) return;
		frm.add_custom_button(__("Quotation"), () => cl_make_quotation(frm), __("Create"));
		frm.add_custom_button(__("Site Visit"), () => cl_make_site_visit(frm), __("Create"));
	},
});

// CRM Lead - Document Cards
// KSEB website buttons + "Required Documents" cards for the Documents child table
// (custom_lead_documents), laid out as in the Hipersign customization prototype.

const DOC_TABLE = "custom_lead_documents";
const DOC_CARDS = "custom_document_cards";

const DOC_STATUS_COLOR = {
	Pending: "orange",
	Received: "blue",
	Verified: "green",
	Cleared: "green",
	Cancelled: "gray",
	Rejected: "red",
};

const DOC_TYPES = [
	"",
	"Aadhaar Card",
	"PAN Card",
	"Electricity Bill",
	"Cheque",
	"Bank Statement",
	"GST Certificate",
	"KSEB Document",
	"Site Photo",
	"Other",
];

const DOC_STATUSES = ["Pending", "Received", "Verified", "Cleared", "Cancelled", "Rejected"];

const DOC_SVG = {
	tower: '<path d="M12 2 8 22M12 2l4 20M6 8h12M5 13h14M7 18h10M9.5 8 14.5 13M14.5 8 9.5 13M9 13l6 5M15 13l-6 5"/>',
	transformer: '<rect x="5" y="9" width="14" height="12" rx="1"/><path d="M8 9V5M12 9V3M16 9V5M8 13v5M12 13v5M16 13v5M3 21h18"/>',
	external: '<path d="M15 3h6v6M10 14 21 3M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/>',
	clip: '<path d="m21.4 11.1-9.2 9.2a6 6 0 0 1-8.5-8.5l9.2-9.2a4 4 0 0 1 5.7 5.7l-9.2 9.2a2 2 0 0 1-2.8-2.8l8.5-8.5"/>',
	dots: '<circle cx="5" cy="12" r="1.6"/><circle cx="12" cy="12" r="1.6"/><circle cx="19" cy="12" r="1.6"/>',
	file: '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6"/>',
};

function doc_svg(name, size, fill) {
	size = size || 18;
	return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="${fill ? "currentColor" : "none"}" stroke="${fill ? "none" : "currentColor"}" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${DOC_SVG[name]}</svg>`;
}

// Website buttons shown above the documents (open in a new tab)
const DOC_LINKS = [
	{
		label: "Visit KSEB Bill Website",
		url: "https://bills.kseb.in/",
		icon: "tower",
		bg: "#e8f0fe",
		border: "#c7d7fb",
		color: "#1d4ed8",
	},
	{
		label: "Feasibility - Transformer Check",
		url: "https://wss.kseb.in/selfservices/reCap",
		icon: "transformer",
		bg: "#dcfce7",
		border: "#b7ebc8",
		color: "#15803d",
	},
];

const DOC_CSS = `
.lead-docs-wrap { display:flex; flex-direction:column; gap:18px; }
.lead-link-row { display:grid; grid-template-columns:repeat(auto-fit,minmax(240px,1fr)); gap:16px; }
.lead-link-tile { display:flex; align-items:center; gap:16px; padding:16px 20px; border-radius:10px; border:1px solid; text-decoration:none !important; font-size:15px; font-weight:600; transition:filter .15s; }
.lead-link-tile:hover { filter:brightness(.97); }
.lead-link-tile .tile-label { flex:1; }
.lead-docs-box { border:1px solid var(--border-color); border-radius:12px; padding:18px 20px; background:var(--card-bg); }
.lead-docs-head { display:flex; justify-content:space-between; align-items:flex-start; gap:8px; }
.lead-docs-title { font-size:16px; font-weight:600; color:var(--heading-color); }
.lead-docs-sub { font-size:13px; color:var(--text-muted); margin-top:2px; }
.lead-docs-count { font-size:13px; color:var(--text-color); white-space:nowrap; }
.lead-docs-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(220px,1fr)); gap:14px; margin-top:16px; }
.lead-doc-card { border:1px solid var(--border-color); border-radius:10px; padding:12px; background:var(--card-bg); display:flex; flex-direction:column; gap:8px; position:relative; }
.lead-doc-card .doc-head { display:flex; justify-content:space-between; align-items:center; gap:6px; }
.lead-doc-card .doc-type { font-weight:600; font-size:14px; color:var(--heading-color); }
.lead-doc-card .doc-menu { border:none; background:transparent; color:var(--text-muted); padding:2px 4px; border-radius:6px; cursor:pointer; }
.lead-doc-card .doc-menu:hover { background:var(--control-bg); }
.lead-doc-card .doc-preview { display:block; height:150px; border-radius:8px; overflow:hidden; background:var(--control-bg); border:1px solid var(--border-color); }
.lead-doc-card .doc-file { font-size:14px; color:var(--text-color); word-break:break-all; }
.lead-doc-card .doc-meta { display:flex; justify-content:space-between; align-items:center; gap:6px; font-size:12px; color:var(--text-muted); }
.lead-docs-empty { margin-top:16px; padding:22px; text-align:center; color:var(--text-muted); border:1px dashed var(--border-color); border-radius:10px; }
.lead-doc-add { margin-top:16px; display:inline-flex; align-items:center; gap:8px; padding:9px 18px; border:1px solid var(--gray-500, #6b7280); border-radius:8px; background:transparent; font-size:14px; font-weight:500; color:var(--text-color); cursor:pointer; }
.lead-doc-add:hover { background:var(--control-bg); }
@media (max-width: 640px) {
  .lead-docs-grid { grid-template-columns:1fr; gap:0; }
  .lead-doc-card { flex-direction:row; align-items:center; border:none; border-bottom:1px solid var(--border-color); border-radius:0; padding:10px 0; }
  .lead-doc-card .doc-preview { width:64px; height:46px; flex:none; order:-1; }
  .lead-doc-card .doc-head { flex:1; flex-direction:column; align-items:flex-start; }
  .lead-doc-card .doc-file, .lead-doc-card .doc-meta { display:none; }
  .lead-doc-add { width:100%; justify-content:center; }
}
`;

function doc_inject_css() {
	if (document.getElementById("lead-docs-css")) return;
	const style = document.createElement("style");
	style.id = "lead-docs-css";
	style.textContent = DOC_CSS;
	document.head.appendChild(style);
}

function doc_safe_url(url) {
	if (!url) return "";
	url = String(url);
	return url.startsWith("/") || url.startsWith("http://") || url.startsWith("https://") ? url : "";
}

function doc_ext(url) {
	const clean = String(url || "").split("?")[0];
	const idx = clean.lastIndexOf(".");
	return idx === -1 ? "" : clean.slice(idx + 1).toLowerCase();
}

function doc_filename(url) {
	const clean = String(url || "").split("?")[0];
	return decodeURIComponent(clean.slice(clean.lastIndexOf("/") + 1));
}

function doc_preview(url) {
	const esc = frappe.utils.escape_html;
	const ext = doc_ext(url);
	if (["png", "jpg", "jpeg", "webp", "gif"].includes(ext)) {
		return `<img src="${esc(url)}" alt="" style="width:100%;height:100%;object-fit:cover;">`;
	}
	const label = ext ? ext.toUpperCase() : "FILE";
	return `<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;gap:4px;color:var(--text-muted);">
			${doc_svg("file", 28)}
			<span style="font-size:11px;font-weight:600;letter-spacing:.04em;">${esc(label)}</span>
		</div>`;
}

function render_document_cards(frm) {
	const field = frm.get_field(DOC_CARDS);
	if (!field) return;
	doc_inject_css();
	const esc = frappe.utils.escape_html;
	const rows = frm.doc[DOC_TABLE] || [];
	const can_edit = frm.perm && frm.perm[0] && frm.perm[0].write && !frm.doc.docstatus;

	const seen = {};
	const cards = rows
		.map((row) => {
			const url = doc_safe_url(row.attachment);
			const color = DOC_STATUS_COLOR[row.status] || "gray";
			const date = row.received_date ? frappe.datetime.str_to_user(row.received_date) : "";
			const title = row.document_name || row.document_type || __("Document");
			seen[title] = (seen[title] || 0) + 1;
			return `
			<div class="lead-doc-card" data-row="${esc(row.name)}">
				<div class="doc-head">
					<span class="doc-type">${esc(title)} (${seen[title]})</span>
					${can_edit || url ? `<button type="button" class="doc-menu" title="${__("Options")}">${doc_svg("dots", 18, true)}</button>` : ""}
				</div>
				<a class="doc-preview" ${url ? `href="${esc(url)}" target="_blank" rel="noopener"` : ""}>
					${url ? doc_preview(url) : `<div style="display:flex;align-items:center;justify-content:center;height:100%;color:var(--text-muted);font-size:12px;">${__("No file")}</div>`}
				</a>
				<div class="doc-file">${esc(url ? doc_filename(url) : "")}</div>
				<div class="doc-meta">
					<span class="indicator-pill ${color}">${esc(__(row.status || "Pending"))}</span>
					<span>${esc(date)}</span>
				</div>
			</div>`;
		})
		.join("");

	const links = DOC_LINKS.map(
		(l) => `<a class="lead-link-tile" href="${esc(l.url)}" target="_blank" rel="noopener noreferrer"
			style="background:${l.bg};border-color:${l.border};color:${l.color};">
			${doc_svg(l.icon, 34)}
			<span class="tile-label">${esc(__(l.label))}</span>
			${doc_svg("external", 20)}
		</a>`
	).join("");

	field.$wrapper.html(`
		<div class="lead-docs-wrap">
			<div class="lead-link-row">${links}</div>
			<div class="lead-docs-box">
				<div class="lead-docs-head">
					<div>
						<div class="lead-docs-title">${__("Required Documents")}</div>
						<div class="lead-docs-sub">${__("Upload the necessary documents for verification.")}</div>
					</div>
					<div class="lead-docs-count">${__("{0} file(s)", [rows.length])}</div>
				</div>
				${
					rows.length
						? `<div class="lead-docs-grid">${cards}</div>`
						: `<div class="lead-docs-empty">${__("No documents yet. Add Aadhaar, electricity bill, cancelled cheque and so on.")}</div>`
				}
				${can_edit ? `<button type="button" class="lead-doc-add">${doc_svg("clip", 18)} ${__("Add Attachment")}</button>` : ""}
			</div>
		</div>
	`);

	field.$wrapper.find(".lead-doc-add").on("click", () => open_document_dialog(frm));
	field.$wrapper.find(".doc-menu").on("click", function (e) {
		e.preventDefault();
		e.stopPropagation();
		const rowname = $(this).closest(".lead-doc-card").attr("data-row");
		show_doc_menu(frm, rowname, this, can_edit);
	});
}

function show_doc_menu(frm, rowname, anchor, can_edit) {
	$(".lead-doc-dropdown").remove();
	const row = (frm.doc[DOC_TABLE] || []).find((r) => r.name === rowname);
	if (!row) return;
	const url = doc_safe_url(row.attachment);
	const items = [];
	if (url) items.push({ label: __("View"), action: () => window.open(url, "_blank", "noopener") });
	if (can_edit) {
		items.push({ label: __("Edit"), action: () => open_document_dialog(frm, row) });
		items.push({ label: __("Remove"), action: () => remove_document(frm, row), danger: true });
	}
	const $menu = $(`<div class="lead-doc-dropdown dropdown-menu show" style="position:absolute;z-index:1050;min-width:140px;"></div>`);
	items.forEach((it) => {
		$(`<a class="dropdown-item" href="#" ${it.danger ? 'style="color:var(--red-600,#dc2626);"' : ""}>${frappe.utils.escape_html(it.label)}</a>`)
			.on("click", (e) => {
				e.preventDefault();
				$menu.remove();
				it.action();
			})
			.appendTo($menu);
	});
	const $card = $(anchor).closest(".lead-doc-card");
	$menu.css({ top: $(anchor).position().top + 28, right: 10 });
	$card.append($menu);
	setTimeout(() => $(document).one("click", () => $menu.remove()), 0);
}

function remove_document(frm, row) {
	frappe.confirm(__("Remove {0}?", [row.document_name || row.document_type || __("this document")]), () => {
		frm.doc[DOC_TABLE] = (frm.doc[DOC_TABLE] || []).filter((r) => r.name !== row.name);
		frm.doc[DOC_TABLE].forEach((r, i) => (r.idx = i + 1));
		frappe.model.clear_doc(row.doctype, row.name);
		frm.refresh_field(DOC_TABLE);
		frm.dirty();
		render_document_cards(frm);
		if (!frm.is_new()) frm.save();
	});
}

function open_document_dialog(frm, row) {
	const editing = !!row;
	const d = new frappe.ui.Dialog({
		title: editing ? __("Edit Document") : __("Add Attachment"),
		fields: [
			{
				fieldname: "document_type",
				fieldtype: "Select",
				label: __("Document Type"),
				options: DOC_TYPES,
				onchange() {
					const type = d.get_value("document_type");
					if (type && !d.get_value("document_name")) d.set_value("document_name", type);
				},
			},
			{
				fieldname: "document_name",
				fieldtype: "Data",
				label: __("Document Name"),
				reqd: 1,
				description: __("Shown on the card, e.g. Aadhaar, Electricity Bill"),
			},
			{ fieldname: "attachment", fieldtype: "Attach", label: __("Upload Document"), reqd: 1 },
			{ fieldtype: "Column Break" },
			{
				fieldname: "status",
				fieldtype: "Select",
				label: __("Status"),
				options: DOC_STATUSES,
				default: "Received",
			},
			{
				fieldname: "received_date",
				fieldtype: "Date",
				label: __("Received Date"),
				default: frappe.datetime.get_today(),
			},
			{ fieldname: "remarks", fieldtype: "Small Text", label: __("Remarks") },
		],
		size: "large",
		primary_action_label: editing ? __("Update") : __("Add"),
		primary_action(values) {
			if (editing) {
				Object.keys(values).forEach((k) => frappe.model.set_value(row.doctype, row.name, k, values[k]));
			} else {
				frm.add_child(DOC_TABLE, values);
			}
			frm.refresh_field(DOC_TABLE);
			render_document_cards(frm);
			d.hide();
			if (!frm.is_new()) frm.save();
		},
	});
	if (editing) {
		d.set_values({
			document_type: row.document_type,
			document_name: row.document_name,
			attachment: row.attachment,
			status: row.status,
			received_date: row.received_date,
			remarks: row.remarks,
		});
	}
	d.show();
}

frappe.ui.form.on("CRM Lead", {
	refresh(frm) {
		render_document_cards(frm);
	},
	custom_lead_documents_add(frm) {
		render_document_cards(frm);
	},
	custom_lead_documents_remove(frm) {
		render_document_cards(frm);
	},
});

frappe.ui.form.on("CRM Lead Document", {
	document_name(frm) {
		render_document_cards(frm);
	},
	document_type(frm, cdt, cdn) {
		const row = locals[cdt][cdn];
		if (row.document_type && !row.document_name) {
			frappe.model.set_value(cdt, cdn, "document_name", row.document_type);
		}
		render_document_cards(frm);
	},
	attachment(frm) {
		render_document_cards(frm);
	},
	status(frm) {
		render_document_cards(frm);
	},
	received_date(frm) {
		render_document_cards(frm);
	},
});

// CRM Lead - Quick Enquiry
// Replaces the standard quick entry for CRM Lead with the "Quick Enquiry" pop-up
// from the Hipersign customization prototype.

(function () {
	const QE_ICONS = {
		user: '<path d="M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/>',
		calendar: '<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/>',
		phone: '<path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1.9.4 1.8.7 2.7a2 2 0 0 1-.5 2.1L8 9.8a16 16 0 0 0 6 6l1.3-1.3a2 2 0 0 1 2.1-.4c.9.3 1.8.6 2.7.7a2 2 0 0 1 1.7 2z"/>',
		bolt: '<path d="M13 2 3 14h9l-1 8 10-12h-9l1-8z"/>',
		pin: '<path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0z"/><circle cx="12" cy="10" r="3"/>',
		doc: '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M16 13H8M16 17H8M10 9H8"/>',
		map: '<path d="M1 6v16l7-4 8 4 7-4V2l-7 4-8-4-7 4z"/><path d="M8 2v16M16 6v16"/>',
	};

	function qe_svg(name, size) {
		size = size || 18;
		return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${QE_ICONS[name]}</svg>`;
	}

	const QE_CSS = `
	.qe-lead .modal-dialog { max-width: 760px; }
	.qe-lead .modal-header { padding: 22px 28px 0; border-bottom: none; align-items: flex-start; }
	.qe-lead .modal-title { font-size: 24px; font-weight: 700; color: var(--heading-color); }
	.qe-lead .qe-sub { font-size: 13px; color: #2563eb; margin-top: 4px; font-weight: 400; }
	.qe-lead .modal-body { padding: 8px 28px 4px; }
	.qe-lead .modal-footer { padding: 12px 28px 22px; border-top: none; justify-content: space-between; }
	.qe-lead .modal-footer .btn { min-width: 110px; padding: 8px 18px; font-size: 14px; }
	.qe-lead .modal-footer .btn-primary { background: #111827; border-color: #111827; }
	.qe-lead .modal-footer .standard-actions { width: 100%; display: flex; justify-content: space-between; }
	.qe-lead .form-section .section-head { font-size: 15px; font-weight: 600; color: var(--heading-color); padding: 0; margin-bottom: 8px; }
	.qe-lead .form-section { padding: 6px 0 0 !important; }
	.qe-lead .frappe-control .control-label { font-size: 13px; font-weight: 500; color: var(--text-color); }
	.qe-lead .qe-has-icon .control-input { position: relative; }
	.qe-lead .qe-has-icon .qe-ico { position: absolute; left: 11px; top: 50%; transform: translateY(-50%); color: var(--text-muted); pointer-events: none; z-index: 2; display: flex; }
	.qe-lead .qe-has-icon[data-fieldtype="Small Text"] .qe-ico { top: 18px; transform: none; }
	.qe-lead .qe-has-icon input.form-control, .qe-lead .qe-has-icon select.form-control, .qe-lead .qe-has-icon textarea.form-control { padding-left: 38px !important; }
	.qe-lead .form-control { min-height: 40px; border-radius: 8px; }
	.qe-lead textarea.form-control { min-height: 96px !important; height: 96px; resize: vertical; }
	.qe-lead .qe-map-btn { position: absolute; right: 0; top: 0; bottom: 0; width: 44px; display: flex; align-items: center; justify-content: center; border-left: 1px solid var(--border-color); color: var(--text-color); cursor: pointer; z-index: 2; background: transparent; border-top: 0; border-right: 0; border-bottom: 0; }
	.qe-lead [data-fieldname="custom_location"] input.form-control { padding-right: 52px !important; }
	.qe-lead .qe-counter { position: absolute; right: 12px; bottom: 8px; font-size: 12px; color: var(--text-muted); z-index: 2; }
	.qe-lead .help-box { font-size: 12px; }
	`;

	function qe_inject_css() {
		if (document.getElementById("qe-lead-css")) return;
		const style = document.createElement("style");
		style.id = "qe-lead-css";
		style.textContent = QE_CSS;
		document.head.appendChild(style);
	}

	function district_options() {
		const df = frappe.meta.get_docfield("CRM Lead", "custom_district");
		return (df && df.options) || "";
	}

	function open_quick_enquiry(opts) {
		opts = opts || {};
		qe_inject_css();
		const prefill = opts.doc || {};

		const d = new frappe.ui.Dialog({
			title: __("Quick Enquiry"),
			fields: [
				{ fieldtype: "Section Break", label: __("Customer Details") },
				{
					fieldname: "first_name",
					fieldtype: "Data",
					label: __("Name"),
					reqd: 1,
					placeholder: __("Customer Name"),
					qe_icon: "user",
				},
				{
					fieldname: "mobile_no",
					fieldtype: "Data",
					label: __("Mobile Number"),
					placeholder: __("Mobile Number"),
					qe_icon: "phone",
				},
				{
					fieldname: "custom_location",
					fieldtype: "Data",
					label: __("Location"),
					placeholder: __("Search location or drop pin"),
					qe_icon: "pin",
				},
				{ fieldtype: "Column Break" },
				{
					fieldname: "custom_date",
					fieldtype: "Date",
					label: __("Date"),
					default: frappe.datetime.get_today(),
					qe_icon: "calendar",
				},
				{
					fieldname: "custom_capacity",
					fieldtype: "Data",
					label: __("Capacity"),
					placeholder: __("e.g. 3 kW, 5 kW, 10 kW"),
					qe_icon: "bolt",
				},
				{
					fieldname: "custom_district",
					fieldtype: "Select",
					label: __("District"),
					options: district_options(),
					qe_icon: "doc",
				},
				{ fieldtype: "Section Break" },
				{
					fieldname: "custom_enquiry_remarks",
					fieldtype: "Small Text",
					label: __("Remarks"),
					placeholder: __("Enter brief details about the enquiry..."),
					qe_icon: "doc",
				},
				{
					fieldname: "custom_referred_by",
					fieldtype: "Link",
					options: "Sales Person",
					label: __("Lead Owner / Referred By"),
					placeholder: __("Select existing lead owner or add new"),
					description: __("You can select an existing lead owner (salesperson) or add a new one."),
					qe_icon: "user",
				},
			],
			primary_action_label: __("Save"),
			primary_action() {
				save_lead(false);
			},
			secondary_action_label: __("Add Detailed Info"),
			secondary_action() {
				save_lead(true);
			},
		});

		d.$wrapper.addClass("qe-lead");
		d.$wrapper
			.find(".modal-title")
			.after(
				`<div class="qe-sub">${__("Add lead with minimal details. You can add more information later.")}</div>`
			)
			.parent()
			.css({ display: "flex", "flex-direction": "column" });

		// icons inside inputs
		d.fields.forEach((df) => {
			if (!df.qe_icon || !df.fieldname) return;
			const field = d.fields_dict[df.fieldname];
			const $ci = field.$wrapper.find(".control-input").first();
			field.$wrapper.addClass("qe-has-icon");
			$ci.prepend(`<span class="qe-ico">${qe_svg(df.qe_icon)}</span>`);
		});

		// map button on Location: uses the device location, else opens Google Maps search
		const $loc = d.fields_dict.custom_location.$wrapper.find(".control-input").first();
		const $map = $(`<button type="button" class="qe-map-btn" title="${__("Drop pin / open map")}">${qe_svg("map")}</button>`);
		$loc.append($map);
		$map.on("click", () => {
			const typed = (d.get_value("custom_location") || "").trim();
			if (typed) {
				window.open("https://www.google.com/maps/search/" + encodeURIComponent(typed), "_blank", "noopener");
				return;
			}
			if (!navigator.geolocation) {
				window.open("https://www.google.com/maps", "_blank", "noopener");
				return;
			}
			frappe.show_alert({ message: __("Getting current location..."), indicator: "blue" });
			navigator.geolocation.getCurrentPosition(
				(pos) => {
					const lat = pos.coords.latitude.toFixed(6);
					const lng = pos.coords.longitude.toFixed(6);
					d.set_value("custom_location", `https://maps.google.com/?q=${lat},${lng}`);
				},
				() => window.open("https://www.google.com/maps", "_blank", "noopener"),
				{ timeout: 10000 }
			);
		});

		// 0/250 counter on remarks
		const rem = d.fields_dict.custom_enquiry_remarks;
		const $ta = rem.$wrapper.find("textarea");
		$ta.attr("maxlength", 250);
		const $counter = $(`<span class="qe-counter">0/250</span>`);
		rem.$wrapper.find(".control-input").first().append($counter);
		const upd = () => $counter.text(`${($ta.val() || "").length}/250`);
		$ta.on("input", upd);

		// footer: Add Detailed Info on the left, Save on the right
		d.get_secondary_btn().removeClass("btn-secondary").addClass("btn-default");

		if (prefill) {
			Object.keys(prefill).forEach((k) => {
				if (d.fields_dict[k] && prefill[k]) d.set_value(k, prefill[k]);
			});
		}

		let saving = false;
		function save_lead(go_detailed) {
			if (saving) return;
			const values = d.get_values();
			if (!values) return;
			saving = true;
			const doc = Object.assign({ doctype: "CRM Lead" }, values);
			Object.keys(doc).forEach((k) => {
				if (doc[k] === "" || doc[k] === null || doc[k] === undefined) delete doc[k];
			});
			frappe
				.call({
					method: "frappe.client.insert",
					args: { doc },
					freeze: true,
					freeze_message: __("Saving lead..."),
				})
				.then((r) => {
					saving = false;
					const saved = r.message;
					if (!saved) return;
					d.hide();
					frappe.show_alert({ message: __("Lead {0} saved", [saved.name]), indicator: "green" });
					frappe.model.sync(saved);
					if (opts.after_insert) {
						opts.after_insert(saved);
						if (!go_detailed) return;
					}
					if (go_detailed) {
						frappe.__lead_open_detailed = saved.name;
						frappe.set_route("Form", "CRM Lead", saved.name);
					} else if (cur_list && cur_list.doctype === "CRM Lead") {
						cur_list.refresh();
					}
				})
				.catch(() => {
					saving = false;
				});
		}

		d.show();
		setTimeout(() => d.fields_dict.first_name.$input && d.fields_dict.first_name.$input.focus(), 300);
		return d;
	}

	frappe.ui.form.open_lead_quick_enquiry = open_quick_enquiry;

	// Hook into frappe.new_doc / make_quick_entry for CRM Lead
	frappe.ui.form.CRMLeadQuickEntryForm = class CRMLeadQuickEntryForm extends frappe.ui.form.QuickEntryForm {
		setup() {
			return new Promise((resolve) => {
				frappe.model.with_doctype(this.doctype, () => {
					const prefill = Object.assign({}, this.doc || {}, frappe.route_options || {});
					frappe.route_options = null;
					this.dialog = open_quick_enquiry({ doc: prefill, after_insert: this.after_insert });
					resolve(this);
				});
			});
		}
	};
})();

