function lead_remarks_counter(frm) {
	const field = frm.get_field("custom_enquiry_remarks");
	if (!field || !field.$wrapper) return;
	const $ta = field.$wrapper.find("textarea");
	if (!$ta.length) return;
	$ta.attr("maxlength", 250);
	const $ci = field.$wrapper.find(".control-input").first().css("position", "relative");
	let $c = $ci.find(".lead-rem-counter");
	if (!$c.length) {
		$c = $(`<span class="lead-rem-counter" style="position:absolute;right:12px;bottom:8px;font-size:12px;color:var(--text-muted);pointer-events:none;"></span>`);
		$ci.append($c);
		$ta.on("input", () => $c.text(`${($ta.val() || "").length}/250`));
	}
	$c.text(`${(frm.doc.custom_enquiry_remarks || "").length}/250`);
}

