// Order Confirmation - Payment Proof Cards
// Payment Details (Advance): Attach + Payment Entry + Print buttons in the section heading; uploaded payment proofs
// (hidden child table payment_proofs) show as cards inside the same section. Print uses the
// "Advance Payment Details" print format.

const OCP_TABLE = "payment_proofs";

function ocp_safe_url(url) {
	url = String(url || "");
	return url.startsWith("/") || url.startsWith("http://") || url.startsWith("https://") ? url : "";
}

function ocp_ext(url) {
	const clean = String(url || "").split("?")[0];
	const i = clean.lastIndexOf(".");
	return i === -1 ? "" : clean.slice(i + 1).toLowerCase();
}

function ocp_preview(url) {
	const esc = frappe.utils.escape_html;
	const ext = ocp_ext(url);
	if (["png", "jpg", "jpeg", "webp", "gif"].includes(ext)) {
		return `<img src="${esc(url)}" alt="" style="width:100%;height:100%;object-fit:cover;">`;
	}
	return `<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;gap:4px;color:var(--text-muted);">
			${frappe.utils.icon("file", "lg")}
			<span style="font-size:11px;font-weight:600;letter-spacing:.04em;">${esc(ext ? ext.toUpperCase() : "FILE")}</span>
		</div>`;
}

function ocp_dialog(frm, row) {
	const editing = !!row;
	const d = new frappe.ui.Dialog({
		title: editing ? __("Edit Payment Proof") : __("Attach Payment Proof"),
		fields: [
			{
				fieldname: "document_name",
				fieldtype: "Data",
				label: __("Document Name"),
				reqd: 1,
				default: editing ? row.document_name : __("Advance Payment"),
				description: __("Shown on the card, e.g. Advance Receipt, UPI Screenshot"),
			},
			{ fieldname: "attachment", fieldtype: "Attach", label: __("Upload File"), reqd: 1, default: editing ? row.attachment : "" },
			{ fieldname: "remarks", fieldtype: "Small Text", label: __("Remarks"), default: editing ? row.remarks : "" },
			{ fieldtype: "Column Break" },
			{
				fieldname: "payment_date",
				fieldtype: "Date",
				label: __("Payment Date"),
				default: editing ? row.payment_date : frm.doc.advance_date || frappe.datetime.get_today(),
			},
			{
				fieldname: "amount",
				fieldtype: "Currency",
				label: __("Amount"),
				default: editing ? row.amount : (frm.doc.payment_proofs || []).length ? 0 : frm.doc.advance_amount,
			},
			{
				fieldname: "mode_of_payment",
				fieldtype: "Link",
				label: __("Mode of Payment"),
				options: "Mode of Payment",
				default: editing ? row.mode_of_payment : frm.doc.mode_of_payment,
			},
		],
		size: "large",
		primary_action_label: editing ? __("Update") : __("Add"),
		primary_action(values) {
			if (editing) {
				Object.keys(values).forEach((k) => (row[k] = values[k]));
			} else {
				frm.add_child(OCP_TABLE, values);
			}
			frm.dirty();
			frm.refresh_field(OCP_TABLE);
			ocp_render(frm);
			d.hide();
			if (!frm.is_new()) frm.save();
		},
	});
	if (editing) {
		d.set_secondary_action_label(__("Delete"));
		d.set_secondary_action(() => {
			frappe.confirm(__("Remove this payment proof?"), () => {
				frm.doc[OCP_TABLE] = (frm.doc[OCP_TABLE] || []).filter((r) => r.name !== row.name);
				(frm.doc[OCP_TABLE] || []).forEach((r, i) => (r.idx = i + 1));
				frm.dirty();
				frm.refresh_field(OCP_TABLE);
				ocp_render(frm);
				d.hide();
				if (!frm.is_new()) frm.save();
			});
		});
	}
	d.show();
}

const OCP_PRINT_FORMAT = "Advance Payment Details";

function ocp_print(frm) {
	const go = () => {
		const params = new URLSearchParams({
			doctype: frm.doctype,
			name: frm.doc.name,
			format: OCP_PRINT_FORMAT,
			no_letterhead: 0,
			trigger_print: 1,
		});
		window.open(`/printview?${params.toString()}`, "_blank");
	};
	if (frm.is_new()) return frappe.msgprint(__("Please save the Order Confirmation first."));
	frm.is_dirty() ? frm.save().then(go) : go();
}

// Payment Entry from Payment Details (Advance).
// Built on the server (API order_confirmation_payment_entry) so party, accounts, amount,
// mode of payment and date arrive already filled; linked to the Sales Order when it is submitted.
async function ocp_payment_entry(frm) {
	if (frm.is_new()) return frappe.msgprint(__("Please save the Order Confirmation first."));
	if (!flt(frm.doc.advance_amount)) return frappe.msgprint(__("Please enter the Advance Amount first."));
	if (frm.is_dirty()) await frm.save();

	const r = await frappe.call({
		method: "order_confirmation_payment_entry",
		args: { name: frm.doc.name },
		freeze: true,
		freeze_message: __("Preparing Payment Entry..."),
	});
	const res = r.message || {};
	if (!res.doc) return;
	const doc = frappe.model.sync(res.doc)[0];
	frappe.set_route("Form", doc.doctype, doc.name);

	if (!res.linked && frm.doc.sales_order) {
		frappe.show_alert(
			{
				message: __("Sales Order {0} is not submitted, so this advance is not linked to it. Submit the Sales Order first to link the advance.", [frm.doc.sales_order]),
				indicator: "orange",
			},
			8
		);
	}
}

function ocp_render(frm) {
	const section = frm.fields_dict.advance_section;
	if (!section || !section.wrapper) return;
	const $section = $(section.wrapper);
	const esc = frappe.utils.escape_html;
	const rows = frm.doc[OCP_TABLE] || [];
	const can_edit = frm.perm && frm.perm[0] && frm.perm[0].write;
	const show_proofs = frm.doc.advance_received !== "No";
	const currency = frappe.defaults.get_default("currency");

	// Buttons in the section heading: Attach + Print
	$section.find(".ocp-toolbar").remove();
	const $head = $section.find(".section-head").first();
	if ($head.length) {
		$head.css({ display: "flex", "align-items": "center", "justify-content": "space-between", gap: "8px" });
		const $bar = $(`<span class="ocp-toolbar" style="display:flex;gap:8px;margin-left:auto;">
			${can_edit && show_proofs ? `<button type="button" class="btn btn-xs btn-default ocp-add">${frappe.utils.icon("attachment", "xs")} ${__("Attach")}</button>` : ""}
			${show_proofs && frappe.model.can_create("Payment Entry") ? `<button type="button" class="btn btn-xs btn-default ocp-pe">${frappe.utils.icon("add", "xs")} ${__("Payment Entry")}</button>` : ""}
			<button type="button" class="btn btn-xs btn-default ocp-print">${frappe.utils.icon("printer", "xs")} ${__("Print")}</button>
		</span>`);
		$head.append($bar);
		$bar.on("click", (e) => e.stopPropagation());
		$bar.find(".ocp-add").on("click", () => ocp_dialog(frm));
		$bar.find(".ocp-pe").on("click", () => ocp_payment_entry(frm));
		$bar.find(".ocp-print").on("click", () => ocp_print(frm));
	}

	// Cards inside the same section, below the payment fields
	$section.find(".ocp-cards").remove();
	if (!show_proofs || !rows.length) return;
	const $body = $section.find(".section-body").first();
	const $target = $body.length ? $body : $section;

	const cards = rows
		.map((row) => {
			const url = ocp_safe_url(row.attachment);
			const date = row.payment_date ? frappe.datetime.str_to_user(row.payment_date) : "";
			const amount = flt(row.amount) ? format_currency(row.amount, currency) : "";
			return `
			<div class="ocp-card" data-row="${esc(row.name)}"
				style="border:1px solid var(--border-color);border-radius:var(--border-radius-md);
				background:var(--card-bg);overflow:hidden;display:flex;flex-direction:column;">
				<a ${url ? `href="${esc(url)}" target="_blank" rel="noopener"` : ""}
					style="display:block;height:110px;background:var(--control-bg);text-decoration:none;">
					${url ? ocp_preview(url) : `<div style="display:flex;align-items:center;justify-content:center;height:100%;color:var(--text-muted);font-size:12px;">${__("No file")}</div>`}
				</a>
				<div style="padding:10px 12px;display:flex;flex-direction:column;gap:6px;flex:1;">
					<div style="font-weight:600;color:var(--heading-color);line-height:1.3;word-break:break-word;">${esc(row.document_name || __("Payment Proof"))}</div>
					${row.mode_of_payment ? `<div style="font-size:12px;color:var(--text-muted);">${esc(row.mode_of_payment)}</div>` : ""}
					<div style="display:flex;align-items:center;justify-content:space-between;gap:6px;margin-top:auto;">
						<span style="font-weight:600;color:#16a34a;">${esc(amount)}</span>
						<span style="font-size:12px;color:var(--text-muted);">${esc(date)}</span>
					</div>
					<div style="display:flex;gap:6px;margin-top:4px;">
						${url ? `<a class="btn btn-xs btn-default" href="${esc(url)}" target="_blank" rel="noopener">${__("View")}</a>` : ""}
						${can_edit ? `<button type="button" class="btn btn-xs btn-default ocp-edit">${__("Edit")}</button>` : ""}
					</div>
				</div>
			</div>`;
		})
		.join("");

	const $cards = $(`<div class="ocp-cards col-sm-12" style="width:100%;flex:0 0 100%;max-width:100%;margin-top:4px;">
		<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px;">${cards}</div>
	</div>`);
	$target.append($cards);
	$cards.find(".ocp-edit").on("click", function () {
		const name = $(this).closest(".ocp-card").attr("data-row");
		const row = (frm.doc[OCP_TABLE] || []).find((r) => r.name === name);
		if (row) ocp_dialog(frm, row);
	});
}

frappe.ui.form.on("Order Confirmation", {
