// Order Confirmation list: status from Payment Details (Advance) > Advance Amount Received,
// and the latest Payment Entry ID opens that Payment Entry.
frappe.listview_settings["Order Confirmation"] = Object.assign(frappe.listview_settings["Order Confirmation"] || {}, {
	add_fields: ["advance_received", "payment_entry"],
	has_indicator_for_draft: true,
	get_indicator(doc) {
		if (doc.advance_received === "Yes") return [__("Received"), "green", "advance_received,=,Yes"];
		if (doc.advance_received === "No") return [__("Not Received"), "red", "advance_received,=,No"];
		return [__("Pending"), "orange", "advance_received,is,not set"];
	},
	formatters: {
		payment_entry(value) {
			if (!value) return "";
			const esc = frappe.utils.escape_html(value);
			const js = JSON.stringify(String(value)).replace(/"/g, "&quot;");
			return `<a href="/app/payment-entry/${encodeURIComponent(value)}" style="color:var(--text-color);text-decoration:underline;" title="${__("Open Payment Entry")}" onclick="event.stopPropagation(); event.preventDefault(); frappe.set_route('Form', 'Payment Entry', ${js}); return false;">${esc}</a>`;
		},
	},
});

// Quotation - CRM Lead Party
