// Quotation - Generate Quotation
// "Generate Quotation" menu next to Create: Preview PDF, Download PDF, Send via WhatsApp,
// Send via Email, Print. All options use the Quotation's default print format.

const GQ_LABEL = "Generate Quotation";

function gq_format(frm) {
	return frm.meta.default_print_format || "Standard";
}

function gq_pdf_url(frm, key) {
	const params = {
		doctype: frm.doctype,
		name: frm.doc.name,
		format: gq_format(frm),
		no_letterhead: 0,
	};
	if (key) params.key = key;
	const qs = Object.keys(params)
		.map((k) => `${encodeURIComponent(k)}=${encodeURIComponent(params[k])}`)
		.join("&");
	return `${frappe.urllib.get_base_url()}/api/method/frappe.utils.print_format.download_pdf?${qs}`;
}

// PDFs are rendered from the saved document, so save pending draft edits first.
function gq_ready(frm) {
	if (frm.is_dirty() && frm.doc.docstatus === 0) {
		return frm.save();
	}
	return Promise.resolve();
}

function gq_preview(frm) {
	gq_ready(frm).then(() => window.open(gq_pdf_url(frm), "_blank"));
}

function gq_download(frm) {
	gq_ready(frm).then(() => {
		frappe.show_alert({ message: __("Preparing PDF..."), indicator: "blue" }, 3);
		fetch(gq_pdf_url(frm), { credentials: "same-origin" })
			.then((res) => {
				if (!res.ok) throw new Error(res.statusText || res.status);
				return res.blob();
			})
			.then((blob) => {
				const a = document.createElement("a");
				a.href = URL.createObjectURL(blob);
				a.download = `${frm.doc.name.replace(/[\/ ]/g, "-")}.pdf`;
				document.body.appendChild(a);
				a.click();
				setTimeout(() => {
					URL.revokeObjectURL(a.href);
					a.remove();
				}, 1000);
			})
			.catch((e) => frappe.msgprint(__("Could not generate the PDF: {0}", [String(e.message || e)])));
	});
}

function gq_phone(raw) {
	let d = String(raw || "").replace(/\D/g, "");
	if (d.length === 11 && d.startsWith("0")) d = d.slice(1);
	if (d.length === 10) d = "91" + d; // local Indian mobile
	return d;
}

function gq_message(frm, link) {
	const d = frm.doc;
	const total = format_currency(d.rounded_total || d.grand_total, d.currency);
	const lines = [
		`Dear ${d.customer_name || d.party_name || "Customer"},`,
		"",
		`Thank you for your interest in ${d.company}. Please find your quotation ${d.name}` +
			(d.custom_total_capacity ? ` for a ${d.custom_total_capacity} solar power system` : "") +
			":",
		link,
		"",
		`Grand Total: ${total}`,
	];
	if (d.valid_till) lines.push(`Valid till: ${frappe.datetime.str_to_user(d.valid_till)}`);
	lines.push("", "Regards,", d.company);
	return lines.join("\n");
}

function gq_whatsapp(frm) {
	gq_ready(frm)
		.then(() => frappe.call({ method: "quotation_share_key", args: { name: frm.doc.name } }))
		.then((r) => {
			const link = gq_pdf_url(frm, r.message);
			const d = new frappe.ui.Dialog({
				title: __("Send via WhatsApp"),
				fields: [
					{
						fieldname: "mobile",
						fieldtype: "Data",
						label: __("WhatsApp Number"),
						reqd: 1,
						default: frm.doc.contact_mobile || frm.doc.contact_phone || "",
						description: __("10-digit numbers get +91 added automatically."),
					},
					{
						fieldname: "message",
						fieldtype: "Small Text",
						label: __("Message"),
						default: gq_message(frm, link),
					},
				],
				primary_action_label: __("Open WhatsApp"),
				primary_action(values) {
					const phone = gq_phone(values.mobile);
					if (phone.length < 11) {
						frappe.msgprint(__("Please enter a valid WhatsApp number."));
						return;
					}
					window.open(`https://wa.me/${phone}?text=${encodeURIComponent(values.message || "")}`, "_blank");
					d.hide();
					frm.add_comment("Comment", __("Quotation shared on WhatsApp with +{0}", [phone]));
				},
			});
			d.show();
		});
}

function gq_email(frm) {
	gq_ready(frm).then(() => {
		const d = frm.doc;
		const composer = new frappe.views.CommunicationComposer({
			doc: d,
			frm: frm,
			subject: `${__("Quotation")} ${d.name} - ${d.company}`,
			recipients: d.contact_email || "",
			attach_document_print: true,
			message: `Dear ${d.customer_name || d.party_name || "Customer"},<br><br>Please find attached our quotation <b>${d.name}</b>` +
				(d.custom_total_capacity ? ` for a ${d.custom_total_capacity} solar power system` : "") +
				`.<br><br>Regards,<br>${d.company}`,
		});
		if (composer.dialog && composer.dialog.fields_dict.select_print_format) {
			composer.dialog.set_value("select_print_format", gq_format(frm));
		}
	});
}

frappe.ui.form.on("Quotation", {
	refresh(frm) {
		if (frm.is_new()) return;

		const label = __(GQ_LABEL);
		frm.add_custom_button(__("Preview PDF"), () => gq_preview(frm), label);
		frm.add_custom_button(__("Download PDF"), () => gq_download(frm), label);
