// Quotation - Order Confirmation
// Green "Order Confirmation" button next to Create (submitted, open quotations).
// Confirming creates a draft Sales Order + an Order Confirmation record (server API quotation_order_confirm)
// and marks the quotation "Order Confirmed".

const OC_GREEN = { "background-color": "#16a34a", "border-color": "#16a34a", color: "#ffffff" };

function oc_place_after_create(frm, $btn) {
	const $create = frm.page.get_inner_group_button(__("Create"));
	if ($btn && $btn.length && $create && $create.length) $btn.insertAfter($create);
}

function oc_confirm(frm) {
	const total = frm.doc.rounded_total || frm.doc.grand_total;
	const d = new frappe.ui.Dialog({
		title: __("Confirm Order"),
		fields: [
			{
				fieldtype: "HTML",
				options: `<p class="text-muted">${__(
					"This marks {0} as Order Confirmed and creates a draft Sales Order from it.",
					[`<b>${frappe.utils.escape_html(frm.doc.name)}</b>`]
				)}</p>`,
			},
			{ fieldname: "quotation_amount", fieldtype: "Currency", label: __("Quotation Amount"), default: total, read_only: 1 },
			{ fieldname: "agreed_amount", fieldtype: "Currency", label: __("Agreed Amount"), default: total },
			{ fieldtype: "Column Break" },
			{ fieldname: "confirmed_amount", fieldtype: "Currency", label: __("Confirmed Amount"), default: total },
			{
				fieldname: "delivery_date",
				fieldtype: "Date",
				label: __("Delivery Date"),
				reqd: 1,
				default: frappe.datetime.get_today(),
				description: __("Used as the Sales Order delivery date"),
			},
		],
		size: "large",
		primary_action_label: __("Confirm Order"),
		primary_action(values) {
			frappe
				.call({
					method: "quotation_order_confirm",
					args: {
						quotation: frm.doc.name,
						delivery_date: values.delivery_date,
						agreed_amount: values.agreed_amount,
						confirmed_amount: values.confirmed_amount,
					},
					freeze: true,
					freeze_message: __("Confirming order..."),
				})
				.then((r) => {
					d.hide();
					const res = r.message || {};
					frm.reload_doc();
					frappe.msgprint({
						title: __("Order Confirmed"),
						indicator: "green",
						message: __("Order Confirmation {0} and draft Sales Order {1} created.", [
							`<a href="/app/order-confirmation/${encodeURIComponent(res.order_confirmation)}">${res.order_confirmation}</a>`,
							`<a href="/app/sales-order/${encodeURIComponent(res.sales_order)}">${res.sales_order}</a>`,
						]),
					});
				});
		},
	});
	d.show();
}

frappe.ui.form.on("Quotation", {
	refresh(frm) {
		if (frm.is_new()) return;
		let $btn = null;

		// Only until the order is confirmed; afterwards just the green "Order Confirmed" status shows.
		if (!frm.doc.custom_order_confirmed && frm.doc.docstatus === 1 && !["Lost", "Expired", "Ordered"].includes(frm.doc.status)) {
			$btn = frm.add_custom_button(__("Order Confirmation"), () => oc_confirm(frm));
		}
		if ($btn) $btn.removeClass("btn-default btn-primary").css(OC_GREEN);

		// After all refresh handlers: put the button right after Create and show the status
		setTimeout(() => {
			oc_place_after_create(frm, $btn);
			if (frm.doc.custom_order_confirmed) frm.page.set_indicator(__("Order Confirmed"), "green");
		}, 0);
	},
});

// Quotation list: order-confirmed quotations show "Ordered" in green instead of "Open".
(function () {
	const settings = (frappe.listview_settings["Quotation"] = frappe.listview_settings["Quotation"] || {});
	settings.add_fields = (settings.add_fields || []).concat(["custom_order_confirmed"]);

	const standard_indicator = settings.get_indicator;
	settings.get_indicator = function (doc) {
		if (cint(doc.custom_order_confirmed) && doc.docstatus === 1 && !["Ordered", "Lost", "Cancelled"].includes(doc.status)) {
			return [__("Ordered"), "green", "custom_order_confirmed,=,1"];
		}
		return standard_indicator ? standard_indicator.call(this, doc) : undefined;
	};
})();

// Solar Package Template - three numbered card sections + package summary
// 1 Main items (package_items: loaded into the quotation, counted in the package amount)
// 2 Fixed items (custom_fixed_items: nuts/bolts/fittings, never shown in the quotation)
// 3 Optional products (custom_optional_items: alternatives / add-ons, offered separately)
// The card header is placed inside the table's own field wrapper, so header and table share one width.

const SPS_SECTIONS = [
	{
		field: "section_items", table: "package_items", n: 1, key: "main",
		title: "Main Package Items (Changeable)",
		sub: "The main products in this package. Brand, model and quantity can be changed. These go into the quotation.",
		hide: ["item_name"],
	},
	{
		field: "custom_fixed_section", table: "custom_fixed_items", n: 2, key: "fixed",
		title: "Fixed Items (Not shown in quotation)",
		sub: "Included in every installation and never shown in the customer quotation.",
		hide: ["item_name", "rate", "discount_amount", "amount"],
	},
	{
		field: "custom_optional_section", table: "custom_optional_items", n: 3, key: "opt",
		title: "Other Optional Products (Not in package)",
		sub: "Alternative brands / additional products that can be added separately if required.",
		hide: ["item_name", "discount_amount", "amount"],
	},
];

function sps_css() {
	if (document.getElementById("sps-style-v3")) return;
	["sps-style", "sps-style-v2"].forEach((id) => { const o = document.getElementById(id); if (o) o.remove(); });
	const s = document.createElement("style");
	s.id = "sps-style-v3";
	s.textContent = `
		.sps-main { --c:#2563eb; --t:#eff6ff; --b:#bfdbfe; }
		.sps-fixed { --c:#059669; --t:#ecfdf5; --b:#a7f3d0; }
		.sps-opt { --c:#ea580c; --t:#fff7ed; --b:#fed7aa; }
		[data-theme="dark"] .sps-main, [data-theme="dark"] .sps-fixed, [data-theme="dark"] .sps-opt { --t: var(--subtle-fg); --b: var(--border-color); }

		.sps-card > .section-head { display:none !important; }
		.sps-card .section-body { padding-top:4px !important; }

		.sps-head { display:flex; align-items:center; gap:12px; padding:12px 14px; background:var(--t);
			border:1px solid var(--b); border-bottom:none; border-radius:12px 12px 0 0; }
		.sps-badge { flex:0 0 30px; width:30px; height:30px; border-radius:50%; background:var(--c); color:#fff;
			display:flex; align-items:center; justify-content:center; font-weight:700; font-size:15px; }
		.sps-titles { flex:1 1 auto; min-width:0; line-height:1.3; }
		.sps-title { color:var(--c); font-weight:700; font-size:15px; }
		.sps-sub { color:var(--text-muted); font-size:12px; margin-top:2px; }
		.sps-add { flex:0 0 auto; border:1px solid var(--border-color); background:var(--card-bg); color:var(--text-color);
			border-radius:8px; padding:5px 12px; font-size:12px; font-weight:600; }
		.sps-add:hover { border-color:var(--c); color:var(--c); }

		.sps-card .form-grid { border:1px solid var(--b) !important; border-radius:0 0 12px 12px !important; overflow:hidden; }
		.sps-card .grid-heading-row { background:var(--subtle-fg); }
		.sps-card .grid-field .control-label { display:none !important; }
		.sps-card .grid-footer .grid-add-row { display:none !important; }
		.sps-card .grid-footer { padding:0 !important; min-height:0; }
		.sps-card .form-grid-container { margin-bottom:0 !important; }

		.sps-summary { display:flex; flex-wrap:wrap; gap:8px; }
		.sps-chip { display:inline-flex; align-items:center; gap:6px; padding:5px 10px; border-radius:999px;
			border:1px solid var(--border-color); background:var(--card-bg); font-size:12px; color:var(--text-muted); }
		.sps-chip b { color:var(--heading-color); font-size:13px; }
		.sps-dot { width:8px; height:8px; border-radius:50%; }
	`;
	document.head.appendChild(s);
}

function sps_columns(frm, sec) {
	const grid = frm.fields_dict[sec.table] && frm.fields_dict[sec.table].grid;
	if (!grid || grid.__sps_cols) return;
	grid.__sps_cols = true;
	const was_dirty = frm.is_dirty();
	try {
		sec.hide.forEach((f) => grid.update_docfield_property(f, "in_list_view", 0));
		grid.visible_columns = null;
		grid.refresh();
	} catch (e) {
		console.warn("sps columns", e);
	}
	// Layout-only change: don't leave the form flagged as "Not Saved".
	if (!was_dirty && frm.is_dirty()) {
		frm.doc.__unsaved = 0;
		frm.refresh_header();
	}
}

function sps_decorate(frm) {
	sps_css();
	SPS_SECTIONS.forEach((sec) => {
		const sf = frm.fields_dict[sec.field];
		const tf = frm.fields_dict[sec.table];
		if (!sf || !tf) return;
		const $sec = $(sf.wrapper).closest(".form-section").length ? $(sf.wrapper).closest(".form-section") : $(sf.wrapper);
		$sec.removeClass("sps-section").removeAttr("style").addClass(`sps-card sps-${sec.key}`);
		$sec.find(".sps-head[data-sps-old]").remove();

		const $field = $(tf.wrapper);
		if (!$field.find("> .sps-head").length) {
			const $head = $(`<div class="sps-head">
				<span class="sps-badge">${sec.n}</span>
				<div class="sps-titles"><div class="sps-title">${__(sec.title)}</div><div class="sps-sub">${__(sec.sub)}</div></div>
				<button type="button" class="sps-add">+ ${__("Add Item")}</button>
			</div>`);
			$head.find(".sps-add").on("click", (e) => {
				e.preventDefault();
				tf.grid.add_new_row(null, null, true);
			});
			$field.prepend($head);
		}
		sps_columns(frm, sec);
	});
}

function sps_summary(frm) {
	const f = frm.fields_dict.custom_package_summary;
	if (!f) return;
	const main = (frm.doc.package_items || []).length;
	const fixed = (frm.doc.custom_fixed_items || []).length;
	const opt = (frm.doc.custom_optional_items || []).length;
	const amt = format_currency(frm.doc.net_package_amount || 0, frappe.defaults.get_default("currency"));
	const chip = (label, v, c) =>
		`<span class="sps-chip">${c ? `<span class="sps-dot" style="background:${c}"></span>` : ""}${label} <b>${v}</b></span>`;
	f.$wrapper.html(`<div class="sps-summary">
		${chip(__("Main"), main, "#2563eb")}
		${chip(__("Fixed"), fixed, "#059669")}
		${chip(__("Optional"), opt, "#ea580c")}
		${chip(__("Total items"), main + fixed + opt)}
		${chip(__("Package amount"), amt)}
	</div>`);
}

frappe.ui.form.on("Solar Package Template", {
	setup(frm) {
		frm.set_query("item_code", "custom_fixed_items", () => ({ filters: { disabled: 0 } }));
		frm.set_query("item_code", "custom_optional_items", () => ({ filters: { disabled: 0, is_sales_item: 1 } }));
