// Work Allocation - Accounting
// Accounting menu: Approve Costs, Post to Accounts, Make Payment, Receive Customer Charges,
// and links to the Journal Entries / Payment Entries / General Ledger / Job Costing report.

const WA_ACC = __("Accounting");

async function wa_ready(frm) {
	if (frm.is_new()) {
		frappe.throw(__("Save the Job Card first."));
	}
	if (frm.is_dirty()) await frm.save();
}

function wa_fmt(v) {
	return format_currency(v, frappe.defaults.get_default("currency"));
}

function wa_line_table(lines, opts) {
	const esc = frappe.utils.escape_html;
	const rows = lines
		.map(
			(c) => `<tr>
				<td style="width:28px;"><input type="checkbox" class="wa-pick" data-key="${esc(c.source_key)}" ${opts.checked ? "checked" : ""}></td>
				<td>${esc(c.source || "")}<div class="text-muted small">${esc(c.expense_type || "")}</div></td>
				<td>${esc(c.payee_name || "")}<div class="text-muted small">${esc(c.party_type || "")}</div></td>
				<td class="text-right">${wa_fmt(opts.outstanding ? c.outstanding_amount : c.amount)}</td>
				${opts.status ? `<td><span class="indicator-pill ${c.approval_status === "Approved" ? "green" : c.approval_status === "Rejected" ? "red" : "orange"}">${esc(__(c.approval_status))}</span></td>` : ""}
			</tr>`
		)
		.join("");
	return `<table class="table table-bordered table-sm" style="margin:0;">
		<thead><tr><th></th><th>${__("Cost")}</th><th>${__("Payable To")}</th><th class="text-right">${
		opts.outstanding ? __("Outstanding") : __("Amount")
	}</th>${opts.status ? `<th>${__("Approval")}</th>` : ""}</tr></thead>
		<tbody>${rows}</tbody></table>`;
}

function wa_picked(d) {
	return d.$wrapper
		.find(".wa-pick:checked")
		.map(function () {
			return $(this).attr("data-key");
		})
		.get();
}

// ---------- Approve / Reject ----------
async function wa_approve(frm) {
	await wa_ready(frm);
	const lines = (frm.doc.costs || []).filter((c) => c.accounting_status === "Not Posted");
	if (!lines.length) {
		frappe.msgprint(__("No cost lines are waiting for approval (posted lines can't be changed)."));
		return;
	}
	const d = new frappe.ui.Dialog({
		title: __("Approve Job Costs"),
		size: "large",
		fields: [
			{
				fieldtype: "HTML",
				fieldname: "lines",
				options: wa_line_table(lines, { checked: true, status: true }),
			},
		],
		primary_action_label: __("Approve Selected"),
		primary_action() {
			wa_cost_action(frm, d, "approve");
		},
		secondary_action_label: __("Reject Selected"),
		secondary_action() {
			wa_cost_action(frm, d, "reject");
		},
	});
	d.show();
}

function wa_cost_action(frm, d, action) {
	const keys = wa_picked(d);
	if (!keys.length) return frappe.msgprint(__("Select at least one line."));
	frappe
		.call({ method: "wa_cost_action", args: { name: frm.doc.name, action, keys: JSON.stringify(keys) }, freeze: true })
		.then((r) => {
			d.hide();
			frm.reload_doc();
			frappe.show_alert({ message: __("{0} line(s) {1}", [(r.message || {}).count || 0, action === "approve" ? __("approved") : __("rejected")]), indicator: action === "approve" ? "green" : "red" });
		});
}

// ---------- Post to Accounts ----------
async function wa_post(frm) {
	await wa_ready(frm);
	const lines = (frm.doc.costs || []).filter((c) => c.approval_status === "Approved" && c.accounting_status === "Not Posted");
	if (!lines.length) {
		frappe.msgprint(__("Nothing to post. Approve the cost lines first."));
		return;
	}
	const total = lines.reduce((s, c) => s + flt(c.amount), 0);
	frappe.confirm(
		__("Create a draft Journal Entry accruing {0} approved cost line(s) totalling {1}? Expense accounts are debited and the payee accounts credited. Submit the Journal Entry to post it.", [lines.length, wa_fmt(total)]),
		() => {
			frappe.call({ method: "wa_post_to_accounts", args: { name: frm.doc.name }, freeze: true, freeze_message: __("Creating Journal Entry...") }).then((r) => {
				const je = (r.message || {}).journal_entry;
				frm.reload_doc();
				if (je) frappe.set_route("Form", "Journal Entry", je);
			});
		}
	);
}

// ---------- Make Payment ----------
async function wa_pay(frm) {
	await wa_ready(frm);
	const lines = (frm.doc.costs || []).filter((c) => c.accounting_status === "Posted" && flt(c.outstanding_amount) > 0.005);
	if (!lines.length) {
		frappe.msgprint(__("No posted, unpaid cost lines. Post the approved costs to accounts and submit the Journal Entry first."));
		return;
	}
	const groups = {};
	lines.forEach((c) => {
		const k = `${c.payee_name} (${c.party_type})`;
		(groups[k] = groups[k] || []).push(c);
	});
	const labels = Object.keys(groups).map((k) => {
		const out = groups[k].reduce((s, c) => s + flt(c.outstanding_amount), 0);
		return { key: k, label: `${k} — ${wa_fmt(out)}` };
	});
	const label_to_key = {};
	labels.forEach((l) => (label_to_key[l.label] = l.key));

	const d = new frappe.ui.Dialog({
		title: __("Make Payment"),
		size: "large",
		fields: [
			{
				fieldname: "payee",
				fieldtype: "Select",
				label: __("Pay To"),
				reqd: 1,
				options: labels.map((l) => l.label),
				default: labels[0].label,
				onchange() {
					render();
				},
			},
			{ fieldname: "lines", fieldtype: "HTML" },
			{ fieldname: "mode_of_payment", fieldtype: "Link", label: __("Mode of Payment"), options: "Mode of Payment", reqd: 1 },
			{ fieldtype: "Column Break" },
			{ fieldname: "posting_date", fieldtype: "Date", label: __("Payment Date"), default: frappe.datetime.get_today(), reqd: 1 },
			{
				fieldname: "amount",
				fieldtype: "Currency",
				label: __("Partial Amount"),
				description: __("Leave blank to pay the full outstanding. A partial amount works when one line is selected."),
			},
		],
		primary_action_label: __("Create Payment"),
		primary_action(values) {
			const keys = wa_picked(d);
			if (!keys.length) return frappe.msgprint(__("Select at least one line."));
			frappe
				.call({
					method: "wa_make_payment",
					args: {
						name: frm.doc.name,
						keys: JSON.stringify(keys),
						mode_of_payment: values.mode_of_payment,
						posting_date: values.posting_date,
						amount: values.amount || 0,
					},
					freeze: true,
					freeze_message: __("Preparing payment..."),
				})
				.then((r) => {
					const res = r.message || {};
					if (!res.doc) return;
					d.hide();
					const doc = frappe.model.sync(res.doc)[0];
					frappe.set_route("Form", doc.doctype, doc.name);
					frappe.show_alert({ message: __("Review and submit the {0} to record the payment.", [__(doc.doctype)]), indicator: "blue" }, 7);
				});
		},
	});
	function render() {
		const key = label_to_key[d.get_value("payee")];
		d.fields_dict.lines.$wrapper.html(wa_line_table(groups[key] || [], { checked: true, outstanding: true }));
	}
	d.show();
	render();
}

// ---------- Receive customer charges ----------
async function wa_receive(frm) {
	await wa_ready(frm);
	const rows = (frm.doc.transactions || []).filter((t) => t.transaction_type === "Collection" && (t.status || "Pending") === "Pending" && flt(t.amount) > 0);
	if (!rows.length) {
		frappe.msgprint(__("No pending Collection charges. Add them in Customer Charges & Authority Payments."));
		return;
	}
	const esc = frappe.utils.escape_html;
	const table = `<table class="table table-bordered table-sm" style="margin:0;"><thead><tr><th></th><th>${__("Charge")}</th><th>${__("Date")}</th><th class="text-right">${__("Amount")}</th></tr></thead><tbody>${rows
		.map(
			(t) => `<tr><td style="width:28px;"><input type="checkbox" class="wa-pick" data-key="${esc(t.name)}" checked></td>
			<td>${esc(t.description === "Other Charges" && t.specify_description ? t.specify_description : t.description)}</td>
			<td>${t.date ? frappe.datetime.str_to_user(t.date) : ""}</td><td class="text-right">${wa_fmt(t.amount)}</td></tr>`
		)
		.join("")}</tbody></table>`;
	const d = new frappe.ui.Dialog({
		title: __("Receive Customer Charges"),
		size: "large",
		fields: [
			{ fieldname: "rows", fieldtype: "HTML", options: table },
			{ fieldname: "mode_of_payment", fieldtype: "Link", label: __("Mode of Payment"), options: "Mode of Payment", reqd: 1 },
			{ fieldtype: "Column Break" },
			{ fieldname: "posting_date", fieldtype: "Date", label: __("Received On"), default: frappe.datetime.get_today(), reqd: 1 },
		],
		primary_action_label: __("Create Payment Entry"),
		primary_action(values) {
			const keys = wa_picked(d);
			if (!keys.length) return frappe.msgprint(__("Select at least one charge."));
			frappe
				.call({ method: "wa_receive_payment", args: { name: frm.doc.name, keys: JSON.stringify(keys), mode_of_payment: values.mode_of_payment, posting_date: values.posting_date }, freeze: true })
				.then((r) => {
					const res = r.message || {};
					if (!res.doc) return;
					d.hide();
					const doc = frappe.model.sync(res.doc)[0];
					frappe.set_route("Form", doc.doctype, doc.name);
				});
		},
	});
	d.show();
}

