// Work Allocation (Job Card) form
// - prefills the 9 timeline milestones
// - pulls customer / project details from the Finalised Quotation
// - progress tracker + delay detection at the top (driven by Status AND milestone dates)
// - live totals, status colour, remarks counter

const WA_MILESTONES = [
	"Feasibility Applied",
	"Feasibility Received",
	"Allocated",
	"Work Started",
	"Work Completed",
	"KSEB / Authority Inspection",
	"Registered",
	"MNRE Process Completed",
	"Subsidy Received",
];

const WA_STATUS_COLOR = {
	Draft: "gray",
	Allocated: "blue",
	"Work Started": "orange",
	"Work Completed": "green",
	Inspection: "purple",
	Registered: "cyan",
	"MNRE Completed": "green",
	Closed: "darkgrey",
};

// Status -> progress stage.
// done_through: index of the last stage the status implies is complete (-1 = none)
// current: stage index to highlight as Current (null = first not-done stage)
// Stages: 0 Feasibility, 1 Allocation, 2 Installation, 3 Inspection, 4 Registration, 5 MNRE, 6 Subsidy, 7 Closed
const WA_STATUS_STAGE = {
	Draft: { done_through: -1, current: null },
	Allocated: { done_through: 1, current: null },
	"Work Started": { done_through: 1, current: 2 },
	"Work Completed": { done_through: 2, current: null },
	Inspection: { done_through: 2, current: 3 },
	Registered: { done_through: 4, current: null },
	"MNRE Completed": { done_through: 5, current: null },
	Closed: { done_through: 7, current: null },
};

function wa_dates(frm) {
	const d = {};
	(frm.doc.milestones || []).forEach((r) => (d[r.milestone] = r.date));
	return d;
}

function wa_prefill_milestones(frm) {
	const have = (frm.doc.milestones || []).map((r) => r.milestone);
	if (have.length) return;
	WA_MILESTONES.forEach((m) => frm.add_child("milestones", { milestone: m }));
	frm.refresh_field("milestones");
}

// Days the work start slipped past "Job To Be Started On"
function wa_start_delay(frm) {
	const planned = frm.doc.job_start_date;
	if (!planned) return null;
	const started = wa_dates(frm)["Work Started"];
	if (started) {
		const days = frappe.datetime.get_day_diff(started, planned);
		return days > 0 ? { days, started: true } : null;
	}
	const days = frappe.datetime.get_day_diff(frappe.datetime.get_today(), planned);
	return days > 0 ? { days, started: false } : null;
}

function wa_render_progress(frm) {
	const field = frm.get_field("progress_html");
	if (!field) return;
	const d = wa_dates(frm);
	const esc = frappe.utils.escape_html;
	const st = WA_STATUS_STAGE[frm.doc.status || "Draft"] || WA_STATUS_STAGE.Draft;
	const stages = [
		{ label: __("Feasibility"), done: !!d["Feasibility Received"] },
		{ label: __("Allocation"), done: !!d["Allocated"] },
		{ label: __("Installation"), done: !!d["Work Completed"] },
		{ label: __("Inspection"), done: !!d["KSEB / Authority Inspection"] },
		{ label: __("Registration"), done: !!d["Registered"] },
		{ label: __("MNRE"), done: !!d["MNRE Process Completed"] },
		{ label: __("Subsidy"), done: !!d["Subsidy Received"] },
		{ label: __("Closed"), done: frm.doc.status === "Closed" },
	];
	// Status implies every earlier stage is complete
	stages.forEach((s, i) => {
		if (i <= st.done_through) s.done = true;
	});
	// Current stage: the one the status points at (if not already done), else first not-done stage
	let current_idx = st.current !== null && !stages[st.current].done ? st.current : stages.findIndex((s) => !s.done);
	const html_stages = stages
		.map((s, i) => {
			const state = s.done ? "done" : i === current_idx ? "current" : "pending";
			const dot =
				state === "done"
					? "background:#16a34a;border-color:#16a34a;"
					: state === "current"
					? "background:#fff;border-color:#2563eb;box-shadow:0 0 0 3px rgba(37,99,235,.18);"
					: "background:var(--control-bg);border-color:var(--border-color);";
			const line =
				i < stages.length - 1
					? `<div style="flex:1;height:2px;margin:0 4px;background:${s.done ? "#16a34a" : "var(--border-color)"};"></div>`
					: "";
			const sub = state === "done" ? __("Done") : state === "current" ? __("Current") : "";
			return `<div style="display:flex;align-items:center;flex:${i < stages.length - 1 ? 1 : 0} 1 auto;min-width:0;">
				<div style="display:flex;flex-direction:column;align-items:center;gap:4px;min-width:64px;">
					<div style="width:14px;height:14px;border-radius:50%;border:2px solid;${dot}"></div>
					<div style="font-size:11px;font-weight:600;color:var(--heading-color);white-space:nowrap;">${esc(s.label)}</div>
					<div style="font-size:10px;color:${state === "done" ? "#16a34a" : "#2563eb"};height:12px;">${esc(sub)}</div>
				</div>${line}</div>`;
		})
		.join("");

	const delay = wa_start_delay(frm);
	const delay_html = delay
		? `<div style="margin-top:10px;display:inline-flex;align-items:center;gap:6px;padding:4px 10px;border-radius:999px;background:#fef2f2;color:#b91c1c;font-size:12px;font-weight:600;">
				&#9888;
				${
					delay.started
						? __("Work started {0} day(s) late", [delay.days])
						: __("Work start overdue by {0} day(s)", [delay.days])
				}
			</div>`
		: "";

	field.$wrapper.html(`
		<div style="overflow-x:auto;padding:4px 2px;">
			<div style="display:flex;align-items:flex-start;min-width:640px;">${html_stages}</div>
		</div>
		${delay_html}
	`);
}

function wa_totals(frm) {
	let incentive = 0,
		coll = 0,
		pay = 0,
		exp = 0;
	(frm.doc.employees || []).forEach((r) => (incentive += flt(r.incentive_amount)));
	(frm.doc.transactions || []).forEach((r) => {
		if (r.transaction_type === "Collection") coll += flt(r.amount);
		else if (r.transaction_type === "Payment") pay += flt(r.amount);
	});
	(frm.doc.expenses || []).forEach((r) => (exp += flt(r.amount)));
	frm.doc.total_incentive = incentive;
	frm.doc.total_collection = coll;
	frm.doc.total_payment = pay;
	frm.doc.net_balance = coll - pay;
	frm.doc.total_expenses = exp;
	["total_incentive", "total_collection", "total_payment", "net_balance", "total_expenses"].forEach((f) =>
		frm.refresh_field(f)
	);
}

function wa_remarks_counter(frm) {
	const n = (frm.doc.remarks || "").length;
	frm.set_df_property("remarks", "description", `${n} / 500`);
}

function wa_indicator(frm) {
	if (frm.is_new()) return;
	const st = frm.doc.status || "Draft";
	frm.page.set_indicator(__(st), WA_STATUS_COLOR[st] || "gray");
}

async function wa_from_quotation(frm) {
	const qn = frm.doc.quotation;
	if (!qn) return;
	const q = await frappe.db.get_doc("Quotation", qn);
	if (q.quotation_to === "Customer" && q.party_name && frm.doc.customer !== q.party_name) {
		await frm.set_value("customer", q.party_name);
	}
	const label = (it) => {
		const qty = flt(it.qty);
		return `${it.item_name} (${qty === Math.trunc(qty) ? qty : qty.toFixed(2)} ${it.uom || "Nos"})`;
	};
	const panels = [],
		inverters = [],
		meters = [];
	(q.items || []).forEach((it) => {
		const n = (it.item_name || it.item_code || "").toLowerCase();
		if (n.includes("inverter")) inverters.push(label(it));
		else if (n.includes("meter")) meters.push(label(it));
		else if (n.includes("panel") || n.includes("module")) panels.push(label(it));
	});
	await frm.set_value({
		plant_capacity: q.custom_total_capacity || "",
		roof_type: q.custom_roof_type || "",
		panel: panels.join(", "),
		inverter: inverters.join(", "),
		net_meter: meters.join(", "),
	});
	const oc = await frappe.db.get_value("Order Confirmation", { quotation: qn }, "name");
	if (oc.message && oc.message.name) await frm.set_value("order_confirmation", oc.message.name);
}

frappe.ui.form.on("Work Allocation", {
	setup(frm) {
		frm.set_query("quotation", () => {
			const f = { docstatus: 1 };
			if (frm.doc.customer) f.party_name = frm.doc.customer;
			return { filters: f };
		});
	},
	onload(frm) {
		if (frm.is_new()) {
			wa_prefill_milestones(frm);
			if (!frm.doc.job_start_date) frm.set_value("job_start_date", frappe.datetime.get_today());
			if (frm.doc.quotation && !frm.doc.plant_capacity) wa_from_quotation(frm);
		}
	},
	refresh(frm) {
		wa_render_progress(frm);
		wa_remarks_counter(frm);
		setTimeout(() => wa_indicator(frm), 0);
		frm.fields_dict.milestones.grid.cannot_add_rows = true;
		frm.fields_dict.milestones.grid.wrapper.find(".grid-add-row").hide();
		frm.set_df_property("milestones", "cannot_delete_rows", 1);
	},
	quotation(frm) {
		wa_from_quotation(frm);
	},
	job_start_date(frm) {
		wa_render_progress(frm);
	},
	status(frm) {
		wa_render_progress(frm);
	},
	remarks(frm) {
		wa_remarks_counter(frm);
	},
	validate(frm) {
		const delay = wa_start_delay(frm);
		if (delay && delay.started) {
			const row = (frm.doc.milestones || []).find((r) => r.milestone === "Work Started");
			if (row && !row.delay_reason) {
				frappe.throw(
					__("Work started {0} day(s) after the planned start date. Please select a Delay Reason on the Work Started row of the Project Timeline.", [
						delay.days,
					])
				);
			}
		}
	},
	employees_remove: wa_totals,
	transactions_remove: wa_totals,
	expenses_remove: wa_totals,
});

frappe.ui.form.on("Work Allocation Milestone", {
	date(frm) {
		wa_render_progress(frm);
	},
});
frappe.ui.form.on("Work Allocation Employee", { incentive_amount: wa_totals });
frappe.ui.form.on("Work Allocation Transaction", { amount: wa_totals, transaction_type: wa_totals });
frappe.ui.form.on("Work Allocation Expense", { amount: wa_totals });

